content.solution_code:
class Tool {
  constructor(name, durability) {
    this.name = name;
    this.durability = durability;
  }

  use() {
    if (this.#isBroken()) {
      return "The tool is broken and cannot be used.";
    }
    this.durability--;
    return `${this.name} used. Durability: ${this.durability}`;
  }

  #isBroken() {
    return this.durability <= 0;
  }
}

class MiningTool extends Tool {
  constructor(name, durability, miningPower) {
    super(name, durability);
    this.miningPower = miningPower;
  }

  mine(material) {
    const useResult = super.use();

    if (useResult.includes("broken")) {
      return useResult;
    }

    return `${this.name} mined ${material} with ${this.miningPower} power! Durability: ${this.durability}`;
  }
}

